"use client";

import { useEffect, useRef, useState } from "react";

import { useDraggable } from "@/hooks/use-draggable";
import { cn } from "@/lib/utils";

import { CanvasRing } from "./canvas-ring";
import { FolderFront } from "./folder-card/folder-front";
import {
  BACK_ASPECT,
  BACK_PATH,
  CARD_WIDTH,
  computeFixedMasonry,
  DURATION,
  EASE,
  FRONT_ASPECT,
  GRID_WIDTH,
  PEEK_COL_WIDTH,
  STAGGER,
  TAP_THRESHOLD,
} from "./folder-card/folder-geometry";
import type {
  CanvasFolderItem,
  FolderOpenState,
  RenderPreview,
} from "./folder-card/folder-geometry";
import { PeekCard } from "./folder-card/peek-card";

export type { CanvasFolderItem, FolderOpenState };

interface FolderCardProps {
  x: number;
  y: number;
  title: string;
  /** Stable id used for marquee selection and the open payload. */
  folderId: string;
  items: readonly CanvasFolderItem[];
  selected?: boolean;
  initialPeeked?: boolean;
  /** Fade the card back so it recedes while another folder is peeked open. */
  dimmed?: boolean;
  openItemId?: string;
  /** Optional 0–100 progress. Falls back to the share of completed items. */
  progress?: number;
  /** Render the preview inside each raised card. */
  renderPreview?: RenderPreview;
  onOpenItem?: (state: FolderOpenState) => void;
  onPeekChange?: (peeked: boolean) => void;
}

export const FolderCard = ({
  x,
  y,
  title,
  folderId,
  items,
  selected,
  initialPeeked,
  dimmed,
  openItemId,
  progress,
  renderPreview,
  onOpenItem,
  onPeekChange,
}: FolderCardProps) => {
  const [hovered, setHovered] = useState(false);
  const [peeked, setPeeked] = useState(initialPeeked ?? false);
  const [cardsRaised, setCardsRaised] = useState(initialPeeked ?? false);
  const [hasBeenPeeked, setHasBeenPeeked] = useState(initialPeeked ?? false);
  const {
    ref: dragRef,
    dragging,
    transform,
    onPointerDown,
    onPointerMove,
    onPointerUp,
  } = useDraggable();

  // Touch tap tracking: a tap toggles peek, a moved gesture is a canvas pan.
  const tapStart = useRef<{ x: number; y: number } | null>(null);
  const tapMoved = useRef(false);

  const togglePeek = () => {
    const next = !peeked;
    setPeeked(next);
    if (next) {
      setHasBeenPeeked(true);
    }
    onPeekChange?.(next);
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    onPointerDown(e);
    if (e.pointerType === "touch") {
      tapStart.current = { x: e.clientX, y: e.clientY };
      tapMoved.current = false;
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    onPointerMove(e);
    if (
      e.pointerType === "touch" &&
      tapStart.current &&
      !tapMoved.current &&
      (Math.abs(e.clientX - tapStart.current.x) > TAP_THRESHOLD ||
        Math.abs(e.clientY - tapStart.current.y) > TAP_THRESHOLD)
    ) {
      tapMoved.current = true;
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    const target = e.target as HTMLElement;

    if (e.pointerType === "touch") {
      // Don't stop propagation: the canvas needs this event to end its pan.
      const wasTap = tapStart.current !== null && !tapMoved.current;
      tapStart.current = null;
      if (wasTap && !target.closest("[data-item-card]")) {
        togglePeek();
      }
      return;
    }

    const wasDragged = onPointerUp();
    if (!wasDragged) {
      if (target.closest("[data-item-card]")) {
        return;
      }
      e.preventDefault();
      e.stopPropagation();
      togglePeek();
    }
  };

  const completedCount = items.filter((i) => i.completed).length;
  const progressValue =
    progress ?? (items.length > 0 ? (completedCount / items.length) * 100 : 0);

  const backH = CARD_WIDTH * BACK_ASPECT;
  const frontH = CARD_WIDTH * FRONT_ASPECT;

  const { gridHeight, positions } = computeFixedMasonry(items.length);

  const peekCenterX = (GRID_WIDTH - PEEK_COL_WIDTH) / 2;

  useEffect(() => {
    if (openItemId && !peeked) {
      setPeeked(true);
      setHasBeenPeeked(true);
    }
  }, [openItemId, peeked]);

  useEffect(() => {
    if (peeked) {
      const id = window.setTimeout(
        () => setCardsRaised(true),
        (DURATION + items.length * STAGGER) * 1000
      );
      return () => clearTimeout(id);
    }
    setCardsRaised(false);
  }, [peeked, items.length]);

  useEffect(() => {
    if (!peeked) {
      return;
    }
    const handleClickOutside = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      if (target.closest("[data-overlay]")) {
        return;
      }
      if (dragRef.current && !dragRef.current.contains(target)) {
        setPeeked(false);
        onPeekChange?.(false);
      }
    };
    // mousedown covers mouse and pen; touch closes via the canvas tap logic.
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, [peeked, dragRef, onPeekChange]);

  return (
    <div
      className={cn(
        "absolute select-none transition-opacity duration-300",
        dimmed && "opacity-30"
      )}
      data-card-id={folderId}
      data-no-pan
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      ref={dragRef}
      style={{
        cursor: dragging ? "grabbing" : "grab",
        height: `${backH}px`,
        left: `${x}px`,
        top: `${y}px`,
        transform,
        width: `${CARD_WIDTH}px`,
        zIndex: dragging ? 50 : undefined,
      }}
    >
      <CanvasRing
        active={dragging || Boolean(selected)}
        variant={selected && !dragging ? "selection" : "drag"}
        thickness={2.5}
      />

      {/* The whole folder scales as one unit on hover (not while peeked). */}
      <div
        className="absolute inset-0"
        style={{
          transform: hovered && !peeked ? "scale(1.02)" : "scale(1)",
          transformOrigin: "center bottom",
          transition: `transform ${DURATION}s ${EASE}`,
        }}
      >
        {/* Back of folder */}
        <svg
          className="absolute inset-0 size-full"
          fill="none"
          onMouseEnter={() => setHovered(true)}
          onMouseLeave={() => setHovered(false)}
          overflow="visible"
          viewBox="0 0 941 791"
        >
          <path d={BACK_PATH} fill="var(--canvas-folder-back)" />
        </svg>

        {/* Item cards, pure CSS transitions, no JS animation library */}
        <div
          className="-translate-x-1/2 absolute left-1/2"
          style={{
            bottom: `${backH + 16}px`,
            height: `${gridHeight}px`,
            pointerEvents: peeked ? "auto" : "none",
            width: `${GRID_WIDTH}px`,
            zIndex: cardsRaised ? 3 : 1,
          }}
        >
          {items.map((item, i) => {
            const pos = positions[i];
            if (!pos) {
              return null;
            }
            return (
              <PeekCard
                backH={backH}
                folderId={folderId}
                frontH={frontH}
                gridHeight={gridHeight}
                hasBeenPeeked={hasBeenPeeked}
                index={i}
                item={item}
                key={item.id}
                onOpenItem={onOpenItem}
                openItemId={openItemId}
                peekCenterX={peekCenterX}
                peeked={peeked}
                pos={pos}
                renderPreview={renderPreview}
                total={items.length}
              />
            );
          })}
        </div>

        <FolderFront
          frontH={frontH}
          itemCount={items.length}
          onHoverChange={setHovered}
          onToggle={togglePeek}
          peeked={peeked}
          progressValue={progressValue}
          title={title}
        />
      </div>
    </div>
  );
};

"use client";

// A peek card is a keyboard-activatable preview tile whose content may itself
// be interactive, a native <button> would be invalid markup, so role="button"
// on a div is intentional. The card is only interactive while the folder is
// peeked open: when closed it is removed from the a11y tree (aria-hidden) and
// the tab order (tabIndex=-1), and onClick early-returns.
// oxlint-disable jsx-a11y/prefer-tag-over-role

import { cn } from "@/lib/utils";

import {
  DURATION,
  EASE,
  PEEK_CARD_HEIGHT,
  PEEK_COL_WIDTH,
  STACK_PEEK_AMOUNT,
  STAGGER,
} from "./folder-geometry";
import type {
  CanvasFolderItem,
  FolderOpenState,
  CardPosition,
  RenderPreview,
} from "./folder-geometry";

const CheckGlyph = ({ className }: { className?: string }) => (
  <svg
    aria-hidden="true"
    className={className}
    fill="none"
    viewBox="0 0 12 12"
    xmlns="http://www.w3.org/2000/svg"
  >
    <path
      d="M2.5 6.2 4.8 8.5 9.5 3.5"
      stroke="currentColor"
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeWidth="1.5"
    />
  </svg>
);

interface PeekCardProps {
  item: CanvasFolderItem;
  index: number;
  total: number;
  pos: CardPosition;
  peeked: boolean;
  hasBeenPeeked: boolean;
  gridHeight: number;
  backH: number;
  frontH: number;
  peekCenterX: number;
  openItemId?: string;
  folderId: string;
  renderPreview?: RenderPreview;
  onOpenItem?: (state: FolderOpenState) => void;
}

export const PeekCard = ({
  item,
  index,
  total,
  pos,
  peeked,
  hasBeenPeeked,
  gridHeight,
  backH,
  frontH,
  peekCenterX,
  openItemId,
  folderId,
  renderPreview,
  onOpenItem,
}: PeekCardProps) => {
  const stackIndex = index - (total - 3);
  const peekY =
    gridHeight + 16 + (backH - frontH) - STACK_PEEK_AMOUNT - stackIndex * 5;

  const tx = peeked ? pos.x : peekCenterX + stackIndex * 3;
  const ty = peeked ? pos.y : peekY;
  const s = peeked ? 1 : 0.55;
  const r = peeked ? 0 : (stackIndex - 1) * 2;
  const isOpenInOverlay = item.id === openItemId;
  const o = peeked || index >= total - 3 ? 1 : 0;
  const delay = peeked ? (total - 1 - index) * STAGGER : 0;

  const revealed = hasBeenPeeked && peeked;
  let body: React.ReactNode;
  if (revealed && renderPreview) {
    body = renderPreview(item, {
      height: PEEK_CARD_HEIGHT,
      index,
      width: PEEK_COL_WIDTH,
    });
  } else if (revealed) {
    body = (
      <div className="flex h-full w-full items-center justify-center bg-background p-3 text-center text-canvas-fg/60 text-xs">
        {item.title}
      </div>
    );
  } else {
    body = (
      <div
        className="bg-background"
        style={{ height: PEEK_CARD_HEIGHT, width: PEEK_COL_WIDTH }}
      />
    );
  }

  return (
    <div
      aria-hidden={!peeked}
      aria-label={item.title}
      className={cn(
        "absolute top-0 left-0 overflow-hidden rounded-xl border border-canvas-border bg-background text-left",
        peeked && "cursor-pointer shadow-xl"
      )}
      data-item-card
      data-item-id={item.id}
      data-no-pan
      onClick={(e) => {
        if (!peeked) {
          return;
        }
        e.stopPropagation();
        const rect = e.currentTarget.getBoundingClientRect();
        onOpenItem?.({
          folderId,
          itemId: item.id,
          sourceRect: rect,
          title: item.title,
        });
      }}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          e.currentTarget.click();
        }
      }}
      // Keep mouse/pen gestures on a peeked card from reaching the folder
      // root, so it never captures the pointer or toggles the peek, the
      // click resolves cleanly to onClick. Touch still bubbles so the canvas
      // can pan.
      onPointerDown={(e) => {
        if (e.pointerType !== "touch") {
          e.stopPropagation();
        }
      }}
      role="button"
      style={{
        height: `${PEEK_CARD_HEIGHT}px`,
        opacity: o,
        transform: `translate3d(${tx}px, ${ty}px, 0) scale(${s}) rotate(${r}deg)`,
        transition: `transform ${DURATION}s ${EASE} ${delay}s, opacity ${DURATION}s ${EASE} ${delay}s`,
        visibility: isOpenInOverlay ? "hidden" : "visible",
        width: `${PEEK_COL_WIDTH}px`,
        willChange: "transform, opacity",
        zIndex: index,
      }}
      tabIndex={peeked ? 0 : -1}
    >
      {body}
      {peeked && item.completed && (
        <div className="absolute top-2 right-2 flex size-5 items-center justify-center rounded-full bg-[var(--canvas-folder-accent)]">
          <CheckGlyph className="size-2.5 text-white" />
          <span className="sr-only">Completed</span>
        </div>
      )}
    </div>
  );
};

"use client";

// The folder face is the toggle for the peek. It can't be a native <button>
// (it wraps an SVG and a flex layout), so role="button" + a key handler give it
// equivalent operability; the revealed peek cards are siblings, not children,
// so this never nests interactive elements.
// oxlint-disable jsx-a11y/prefer-tag-over-role

import { motion } from "motion/react";

import { CircularProgress } from "@/components/ui/circular-progress";

import {
  DURATION,
  EASE,
  FRONT_PATH,
  FRONT_TRANSITION,
} from "./folder-geometry";

interface FolderFrontProps {
  frontH: number;
  peeked: boolean;
  progressValue: number;
  itemCount: number;
  title: string;
  onHoverChange: (hovered: boolean) => void;
  onToggle: () => void;
}

export const FolderFront = ({
  frontH,
  peeked,
  progressValue,
  itemCount,
  title,
  onHoverChange,
  onToggle,
}: FolderFrontProps) => (
  <div
    className="absolute inset-x-0 bottom-0 z-[2] [perspective:800px]"
    style={{ height: `${frontH}px` }}
  >
    <motion.div
      animate={{
        rotateX: peeked ? -16 : 0,
      }}
      aria-expanded={peeked}
      aria-label={title}
      className="size-full origin-bottom rounded-[20px] shadow-[0_2px_8px_rgba(0,0,0,0.04),0_8px_24px_rgba(0,0,0,0.06)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-canvas-fg/25"
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onToggle();
        }
      }}
      onMouseEnter={() => onHoverChange(true)}
      onMouseLeave={() => onHoverChange(false)}
      role="button"
      tabIndex={0}
      transition={FRONT_TRANSITION}
    >
      <svg
        className="absolute inset-0 size-full"
        fill="none"
        overflow="visible"
        viewBox="0 0 941 657"
      >
        <path d={FRONT_PATH} fill="var(--canvas-folder-front)" />
      </svg>

      <div className="absolute inset-0 flex flex-col justify-between px-[22px] pt-5 pb-[22px]">
        <div
          className="flex justify-center"
          style={{
            transform: peeked ? "translateY(-3px)" : "translateY(0)",
            transition: `transform ${DURATION}s ${EASE}`,
          }}
        >
          <CircularProgress
            className="size-[34px]"
            strokeWidth={3}
            style={{
              color:
                progressValue === 100
                  ? "var(--canvas-folder-accent)"
                  : "var(--canvas-folder-fg-muted)",
            }}
            value={progressValue}
          />
        </div>
        <div>
          <p className="m-0 text-[13px] text-[var(--canvas-folder-fg-muted)] leading-[1.3]">
            {itemCount} {itemCount === 1 ? "Item" : "Items"}
          </p>
          <h3 className="mt-0.5 mb-0 text-[16px] text-[var(--canvas-folder-fg)] leading-[1.25] font-bold">
            {title}
          </h3>
        </div>
      </div>
    </motion.div>
  </div>
);
